<?php require 'config.php';verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['food_id'])){$fid=(int)$_POST['food_id'];$s=$pdo->prepare("SELECT f.id,f.restaurant_id FROM foods f JOIN restaurants r ON r.id=f.restaurant_id WHERE f.id=? AND f.available=1 AND r.approved=1");$s->execute([$fid]);$f=$s->fetch();if($f){$cart=$_SESSION['cart']??[];if($cart&&isset($_SESSION['cart_restaurant'])&&$_SESSION['cart_restaurant']!=$f['restaurant_id']){flash('Your cart can contain items from one restaurant only.','warning');}else{$cart[$fid]=($cart[$fid]??0)+1;$_SESSION['cart']=$cart;$_SESSION['cart_restaurant']=(int)$f['restaurant_id'];flash('Food added to cart.');}}redirect('cart.php');}
if(isset($_GET['remove'])){$fid=(int)$_GET['remove'];unset($_SESSION['cart'][$fid]);if(empty($_SESSION['cart']))unset($_SESSION['cart_restaurant']);redirect('cart.php');}
$items=[];$total=0;$cart=$_SESSION['cart']??[];if($cart){$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM foods WHERE id IN ($in)");$s->execute($ids);foreach($s as $f){$q=(int)$cart[$f['id']];$items[]=['food'=>$f,'qty'=>$q];$total+=(float)$f['price']*$q;}}
$pageTitle='Your cart';include 'partials/header.php';?>
<h1>Your cart</h1><?php if(!$items):?><p>Your cart is empty. <a href="restaurants.php">Browse restaurants</a></p><?php else:?><div class="table-wrap"><table><tr><th>Food</th><th>Price</th><th>Quantity</th><th>Subtotal</th><th></th></tr><?php foreach($items as $it):$f=$it['food'];?><tr><td><?=e($f['name'])?></td><td>৳<?=number_format((float)$f['price'],2)?></td><td><?=$it['qty']?></td><td>৳<?=number_format((float)$f['price']*$it['qty'],2)?></td><td><a href="cart.php?remove=<?=$f['id']?>">Remove</a></td></tr><?php endforeach;?></table></div><h2>Total: <span class="price">৳<?=number_format($total,2)?></span></h2><a class="btn" href="checkout.php">Proceed to checkout</a><?php endif;?><?php include 'partials/footer.php';?>
